#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{" 5\n"};
    char actual = '?';

    while (entrada.get(actual)) {
        if (actual == ' ') {
            std::cout << "ESPACIO\n";
        } else if (actual == '\n') {
            std::cout << "SALTO\n";
        } else {
            std::cout << "CARACTER:" << actual << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"\n+ 4"};
    char actual = '?';

    while (entrada.get(actual)) {
        if (actual == ' ') {
            std::cout << "E";
        } else if (actual == '\n') {
            std::cout << "S";
        } else {
            std::cout << actual;
        }
    }

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"3+8"};
    char actual = '?';

    while (entrada.get(actual)) {
        if (actual >= '0' && actual <= '9') {
            const int valor = actual - '0';
            std::cout << "Valor: " << valor << "\n";
        } else {
            std::cout << "Signo: " << actual << "\n";
        }
    }

    return 0;
}

