#include <iostream>
#include <sstream>

int main() {
    std::istringstream entrada{"2\t* 9\n"};
    char actual = '?';
    int digitos = 0;
    int separadores = 0;
    int otros = 0;

    while (entrada.get(actual)) {
        if (actual >= '0' && actual <= '9') {
            ++digitos;
        } else if (actual == ' ' || actual == '\t' || actual == '\n') {
            ++separadores;
        } else {
            ++otros;
        }
    }

    std::cout << "Digitos: " << digitos;
    std::cout << "\nSeparadores: " << separadores;
    std::cout << "\nOtros: " << otros;

    return 0;
}

